def generate_grand_test_questions():
    specs = get_grand_test_raw_specs()
    assert len(specs) == 100, f"Expected 100 specs, got {len(specs)}"

    qs = []
    for item in specs:
        (num, subtopic, diff,
         en_stem, ta_stem,
         en_a, ta_a, en_b, ta_b, en_c, ta_c, en_d, ta_d, correct_key,
         exp_en, exp_ta,
         why_a_en, why_a_ta, why_b_en, why_b_ta, why_c_en, why_c_ta, why_d_en, why_d_ta,
         tip_en, tip_ta, fact_en, fact_ta) = item

        qid = f"PPPG_GT_{num}"
        q = make_pppg_q(
            qid, diff, "multiple_choice", subtopic,
            en_stem, ta_stem,
            en_a, ta_a, en_b, ta_b, en_c, ta_c, en_d, ta_d,
            correct_key,
            exp_en, exp_ta,
            why_a_en, why_a_ta, why_b_en, why_b_ta, why_c_en, why_c_ta, why_d_en, why_d_ta,
            tip_en, tip_ta, fact_en, fact_ta
        )
        qs.append(q)

    # 1. Collision check against Core questions (325 questions)
    core_files = [
        "data/questions/polity/political_parties_pressure_groups_easy.json",
        "data/questions/polity/political_parties_pressure_groups_medium.json",
        "data/questions/polity/political_parties_pressure_groups_hard.json",
        "data/questions/polity/political_parties_pressure_groups_statement_based.json",
        "data/questions/polity/political_parties_pressure_groups_pyq.json",
        "data/questions/polity/political_parties_pressure_groups_reasoning.json",
        "data/questions/polity/political_parties_pressure_groups_match_the_following.json",
        "data/questions/polity/political_parties_pressure_groups_chronology.json"
    ]
    dup_index = TopicDuplicateIndex("political_parties_pressure_groups")
    loaded = dup_index.load_from_files(core_files)
    print(f"Loaded {loaded} Core questions into Duplicate Index.")

    collisions = []
    for q in qs:
        is_dup, reason = dup_index.check_duplicate(q["question_en"], q["question_ta"])
        if is_dup:
            collisions.append((q["id"], reason))

    if collisions:
        print(f"FAIL: Found {len(collisions)} duplicate collisions with Core questions:")
        for cid, reason in collisions[:10]:
            print(f"  - {cid}: {reason}")
        raise ValueError("Collision check failed!")
    else:
        print("PASS: 0 collisions detected against Core (325 questions).")

    # 2. Randomize and balance dataset (exact 25 A, 25 B, 25 C, 25 D)
    balanced_qs = randomize_and_balance_dataset(qs, seed=3042)
    keys = [q["correct_answer"] for q in balanced_qs]
    key_counts = Counter(keys)
    print("Grand Test Balanced Key counts:", key_counts)
    assert key_counts == {"A": 25, "B": 25, "C": 25, "D": 25}, f"Unbalanced Grand Test keys: {key_counts}"

    # 3. Content Validation
    validator = ContentValidator()
    all_errors = []
    for q in balanced_qs:
        errs = validator.validate_question(q)
        if errs:
            all_errors.extend(errs)

    if all_errors:
        print(f"Validation failed with {len(all_errors)} errors:")
        for err in all_errors[:10]:
            print(f"  - {err}")
        raise ValueError("Content Validation failed!")

    out_file = "data/questions/polity/political_parties_pressure_groups_grand_test.json"
    os.makedirs(os.path.dirname(out_file), exist_ok=True)
    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(balanced_qs, f, ensure_ascii=False, indent=2)

    print(f"Successfully wrote {len(balanced_qs)} Grand Test MCQs to {out_file}")

if __name__ == "__main__":
    generate_grand_test_questions()
